# --- lang-words: generated by lang/build.py from lang/phrases.json, don't edit by hand ---
# The word rules in 35 languages. Search lang_norm(text) with these, except MONTHS (raw text).
_LANG_MARKS = re.compile("[\u0300-\u036f\u0591-\u05bd\u05bf\u05c1\u05c2\u05c4\u05c5\u05c7\u064b-\u065f\u0670]")
_LANG_SAME = str.maketrans({"\u2019": "'", "\u2018": "'", "\u02bc": "'", "`": "'", "\u03c2": "\u03c3", "\u064a": "\u06cc", "\u0649": "\u06cc", "\u0643": "\u06a9", "\u200c": "", "\u200d": ""})


def lang_norm(text):
    """Lower case, accents removed: how the phrases below are written."""
    t = unicodedata.normalize("NFD", str(text or "").lower())
    return unicodedata.normalize("NFC", _LANG_MARKS.sub("", t)).translate(_LANG_SAME)


